REVOKE ALL ON FUNCTION public.get_public_inspection_approval(uuid) FROM PUBLIC, anon, authenticated; GRANT EXECUTE ON FUNCTION public.get_public_inspection_approval(uuid) TO service_role; REVOKE ALL ON FUNCTION public.submit_public_inspection_approval(uuid,uuid[]) FROM PUBLIC, anon, authenticated; GRANT EXECUTE ON FUNCTION public.submit_public_inspection_approval(uuid,uuid[]) TO service_role;